  var n = parseInt(input[0]);
  tmp = input[1].split(" ");
  a = new Array(n);
  var odd=0;
  var even=0;
  var four=0;
  for(i=0;i<n;i++){
    a[i]=parseInt(tmp[i]);
    if(a[i]%4==0){
      four++;
